import{_ as t,o as a,c as p,a4 as s}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"鸡蛋为啥“一天一个价”？2026-06-18","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"鸡蛋为啥“一天一个价”？2026-06-18","date":"2026-06-18T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202606/t20260618_6485117.htm","summary":"农民日报全媒体记者　于涵阳\\n近期，不少消费者感受到，超市里的鸡蛋价格较今年一季度大幅上涨，在北京市朝阳区的一家便民超市里，记者询问了鸡蛋价格波动的情况。店主回答，年初鸡蛋价格基本稳定在每斤4元左右，如今涨到5至6元。\\n记者进一步了解到，自5月以来，全国鸡蛋价格连续五周上行，创下近五年同期价格新高，多地市场呈现“一天一个价”的上涨态势。...\\n","contentHash":"58d65d0b52b3ede609abf650955a2f04","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-06-18-鸡蛋为啥-一天一个价.md","filePath":"policies/2026-06-18-鸡蛋为啥-一天一个价.md"}'),r={name:"policies/2026-06-18-鸡蛋为啥-一天一个价.md"};function o(_,e,n,l,c,i){return a(),p("div",null,[...e[0]||(e[0]=[s('<h1 id="鸡蛋为啥-一天一个价-2026-06-18" tabindex="-1">鸡蛋为啥“一天一个价”？2026-06-18 <a class="header-anchor" href="#鸡蛋为啥-一天一个价-2026-06-18" aria-label="Permalink to &quot;鸡蛋为啥“一天一个价”？2026-06-18&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202606/t20260618_6485117.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-06-18 摘要: 农民日报全媒体记者　于涵阳 近期，不少消费者感受到，超市里的鸡蛋价格较今年一季度大幅上涨，在北京市朝阳区的一家便民超市里，记者询问了鸡蛋价格波动的情况。店主回答，年初鸡蛋价格基本稳定在每斤4元左右，如今涨到5至6元。 记者进一步了解到，自5月以来，全国鸡蛋价格连续五周上行，创下近五年同期价格新高，多地市场呈现“一天一个价”的上涨态势。...</p></blockquote><p>近期，不少消费者感受到，超市里的鸡蛋价格较今年一季度大幅上涨，在北京市朝阳区的一家便民超市里，记者询问了鸡蛋价格波动的情况。店主回答，年初鸡蛋价格基本稳定在每斤4元左右，如今涨到5至6元。</p><p>记者进一步了解到，自5月以来，全国鸡蛋价格连续五周上行，创下近五年同期价格新高，多地市场呈现“一天一个价”的上涨态势。带着市场普遍关心的系列疑问，记者采访了中央财经大学教授、国家蛋鸡产业技术体系产业经济岗位科学家于爱芝和北京蛋品加工销售行业协会会长王忠强等业内专家。</p><p>专家认为，本轮蛋价上涨是2025年蛋鸡市场长期低迷后的合理价格修复。去年，国内蛋鸡养殖业遭遇长时间、大范围的亏损。行情低谷期，全国全年鸡蛋均价仅3.2元/斤，个别月份价格甚至低于饲料养殖成本。部分养殖主体无奈提前淘汰存栏蛋鸡，产能去化加速。与此同时，行业整体悲观情绪浓厚，中小养殖户观望心态加剧，一方面淘汰鸡增速上升，另一方面，鸡苗补栏规模及速度下降，特别是2025年三季度以来鸡苗补栏量急速下滑。由于蛋鸡养殖存在4至5个月的生长周期，去年的补栏低迷，精准对应2026年二季度新开产蛋鸡产能缺口，市场形成“老鸡已淘汰出清、新鸡未集中开产”的产能断档局面。</p><p>数据显示，今年5月全国在产蛋鸡存栏量降至约12.79亿只，环比下降1.24%，同比下降4.24%。当前养殖企业鸡蛋库存普遍维持在0至1天，市场基本实现“产出即售罄”，供给端紧张态势凸显。</p><p>需求端的集中释放，进一步加剧供需失衡格局。随着端午节临近，国内食品加工企业开始粽子、糕点等节令产品集中备货，蛋类阶段性刚需大幅提升。同时，线下餐饮复苏、烘焙行业稳步发展，带动工业用蛋需求持续增长，多重需求叠加，持续消化市场存量鸡蛋。</p><p>此外，夏季特殊气候加剧了市场供给紧张。夏季高温环境会自然降低蛋鸡产蛋效率，造成天然减产。南方地区进入梅雨季，潮湿闷热的天气易导致鸡蛋变质损耗，鸡蛋收购商普遍不敢囤货备货，全产业链形成“随采随销、零库存周转”的经营模式，极低的库存水平大幅放大了鸡蛋价格的波动弹性，助推价格持续走高。</p><p>专家指出，本轮蛋价上涨呈现出淡季反常、持续攀升、涨幅突出的鲜明特征，并非短期市场炒作导致，而是去年行业深度亏损引发的产能收缩，叠加阶段性需求释放、极端天气影响流通等多重因素共同作用的结果。好消息是，目前国内蛋鸡养殖端已摆脱亏损状态，实现稳健盈利。</p><p>针对后续蛋价走势，行业专业人士作出阶段性预判。王忠强分析，随着南方梅雨季推进，鸡蛋终端流通速度加快，短期市场供需紧张格局将略有缓解，蛋价有望迎来小幅回落。</p><p>从中长期行情来看，蛋价将呈现阶段性涨跌分化态势。7至8月，夏季高温带来的蛋鸡减产效应将持续显现，叠加中秋、开学季前置备货需求启动，鸡蛋价格大概率再度迎来回升行情。</p><p>进入四季度，市场格局或将迎来逆转。今年3月以来新增补栏的鸡苗，将在四季度全面进入产蛋高峰期，鸡蛋供给量大幅提升，届时国内蛋价有望迎来趋势性回落，行业高价行情将逐步降温。</p><p>针对本轮网传“蛋价涨幅近八成”的热点，业内专家作出客观解读，提醒市场和消费者理性看待数据波动。于爱芝介绍，“近八成涨幅”说法，对比基准为2025年鸡蛋市场的历史低位价格，其并不具备与正常年份行情对比的参考意义，无需过度放大行情波动。</p><p>从行业长期发展来看，近几年国内鸡蛋价格整体波动幅度可控，淡旺季价格差异化逐步缩小，行业运行日趋平稳。于爱芝建议，未来蛋鸡养殖行业不能单纯依赖行情周期获利，更需聚焦质量安全提升与产品差异化竞争，通过标准化养殖、品牌化运营、多元化产品开发，稳定市场供给，推动蛋鸡产业从粗放式养殖向高质量、稳定可控的现代化养殖转型。</p><p><a href="https://scs.moa.gov.cn/gzdt/202606/t20260618_6485117.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',15)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
